#include "jme/jme.h"
#include <math.h>

/*
 * VSOP87A (Bretagnon & Francou 1988): heliocentric rectangular coordinates,
 * ecliptic and equinox J2000, all terms of the official IMCCE files
 * (src/vsop87a_data.inc, generated by tools/gen_vsop87a.py).
 *
 * Each coordinate is  sum_a T^a S_a(T),  S_a = sum_i A_i cos(B_i + C_i T),
 * T in Julian millennia TDB from J2000. The velocity is the exact analytic
 * derivative of the same series,
 *   d/dT = sum_a [ a T^(a-1) S_a + T^a S'_a ],  S'_a = -sum_i A_i C_i sin(B_i + C_i T),
 * so position and velocity are mutually consistent to rounding (no finite
 * differences). Series sums use Neumaier compensated summation.
 */
#include "vsop87a_data.inc"

#define JME_VSOP87_DAYS_PER_MILLENNIUM 365250.0

static int vsop87_body_index(int body)
{
    switch (body) {
    case JME_BODY_MERCURY:
        return 0;
    case JME_BODY_VENUS:
        return 1;
    case JME_BODY_EARTH:
        return 2;
    case JME_BODY_MARS:
        return 3;
    case JME_BODY_JUPITER:
        return 4;
    case JME_BODY_SATURN:
        return 5;
    case JME_BODY_URANUS:
        return 6;
    case JME_BODY_NEPTUNE:
        return 7;
    case JME_BODY_EARTH_MOON_BARYCENTER:
        return 8;
    default:
        return -1;
    }
}

static void neumaier_add(double *sum, double *comp, double x)
{
    double t = *sum + x;
    if (fabs(*sum) >= fabs(x)) {
        *comp += (*sum - t) + x;
    } else {
        *comp += (x - t) + *sum;
    }
    *sum = t;
}

/* Position (au) and velocity (au per millennium) of one series body. */
static void vsop87_series(int bi, double t, double *pos, double *vel)
{
    int coord, power, i;

    for (coord = 0; coord < 3; coord++) {
        double value = 0.0, value_c = 0.0, deriv = 0.0, deriv_c = 0.0;
        double tp = 1.0;   /* T^power */
        double tpm1 = 0.0; /* T^(power-1), 0 for power 0 */
        for (power = 0; power < 6; power++) {
            int start = jme_vsop87a_index[bi][coord][power][0];
            int count = jme_vsop87a_index[bi][coord][power][1];
            double s = 0.0, s_c = 0.0, ds = 0.0, ds_c = 0.0;
            for (i = start; i < start + count; i++) {
                double a = jme_vsop87a_terms[i][0];
                double b = jme_vsop87a_terms[i][1];
                double c = jme_vsop87a_terms[i][2];
                double arg = b + c * t;
                neumaier_add(&s, &s_c, a * cos(arg));
                neumaier_add(&ds, &ds_c, -a * c * sin(arg));
            }
            s += s_c;
            ds += ds_c;
            if (count > 0) {
                neumaier_add(&value, &value_c, tp * s);
                neumaier_add(&deriv, &deriv_c, tp * ds);
                if (power > 0) {
                    neumaier_add(&deriv, &deriv_c, (double)power * tpm1 * s);
                }
            }
            tpm1 = tp;
            tp *= t;
        }
        pos[coord] = value + value_c;
        if (vel != 0) {
            vel[coord] = deriv + deriv_c;
        }
    }
}

int jme_vsop87_planet_state(double jd_et, int body, double *results)
{
    double t;
    double pos[3], vel[3];
    int bi, i;

    if (results == 0) {
        return JME_ERR;
    }
    for (i = 0; i < 6; i++) {
        results[i] = 0.0;
    }
    if (!isfinite(jd_et)) {
        return JME_ERR;
    }
    /* two-part reduction keeps the full resolution of jd_et */
    t = ((jd_et - 2451545.0)) / JME_VSOP87_DAYS_PER_MILLENNIUM;

    if (body == JME_BODY_MOON) {
        /* VSOP87 Earth and Earth-Moon barycentre give the Moon through the
         * Moon/Earth mass ratio used by VSOP87 (0.01230073677). */
        double e[3], ev[3], m[3], mv[3];
        const double f = 1.0 + 1.0 / 0.01230073677;
        vsop87_series(2, t, e, ev);
        vsop87_series(8, t, m, mv);
        for (i = 0; i < 3; i++) {
            pos[i] = (m[i] - e[i]) * f + e[i];
            vel[i] = (mv[i] - ev[i]) * f + ev[i];
        }
    } else {
        bi = vsop87_body_index(body);
        if (bi < 0) {
            return JME_ERR;
        }
        vsop87_series(bi, t, pos, vel);
    }
    for (i = 0; i < 3; i++) {
        results[i] = pos[i];
        results[i + 3] = vel[i] / JME_VSOP87_DAYS_PER_MILLENNIUM;
        if (!isfinite(results[i]) || !isfinite(results[i + 3])) {
            return JME_ERR;
        }
    }
    return JME_OK;
}
